/* The EVN ALPHA IDE's service worker (docs/curriculum/OFFLINE_DESIGN.md §8.2, O6). Generated by
   scripts/build_web_ide.js (scripts/ide_offline.js); do not edit by hand. */
'use strict';
const VERSION = "0.2.77+e49d821325c3";
const LIST_SHA256 = "3256be641b3c0f83dbf4d69f58c0977ebb44ccabfd69309fe481ba5ba88711e1";
const PASS = ["extensions/evn-alpha/media/pyodide/"];
const KILL = false;

const PREFIX = 'evn-ide-';
const CACHE = PREFIX + VERSION;
const META = PREFIX + 'meta';
const PAGE = 'index.html';
const PAGE_TIMEOUT_MS = 3000;
const SCOPE = new URL(self.registration.scope);
const mem = { lists: new Map(), clients: new Map() };

const metaKey = (k) => new URL('__evn-meta/' + k, SCOPE).href;
async function metaGet(k) {
    const r = await (await caches.open(META)).match(metaKey(k));
    return r ? r.text() : null;
}
/** the meta cache is made at install only: a write after ?evn-sw=off deleted it does not make it again */
async function metaPut(k, v, create) {
    if (!create && !(await caches.has(META))) { return; }
    await (await caches.open(META)).put(metaKey(k), new Response(v));
}

async function sha256Hex(buf) {
    const d = new Uint8Array(await crypto.subtle.digest('SHA-256', buf));
    let s = '';
    for (let i = 0; i < d.length; i++) { s += d[i].toString(16).padStart(2, '0'); }
    return s;
}
/** the one hash test every served, cached and reused file passes (scripts/test_ide_offline.js's mutant drops it) */
function sameHash(got, want) { return got === want; }

const rebuild = (res, buf) => new Response(buf, { status: res.status, statusText: res.statusText, headers: res.headers });
const urlOf = (rel) => new URL(rel, SCOPE).href;

/** a version's offline.json: kept in evn-ide-meta; this version's is fetched and checked against LIST_SHA256; another
 *  version's is taken from the site only when the site's list is that version (the page came from the site) */
async function listFor(version, installing) {
    if (mem.lists.has(version)) { return mem.lists.get(version); }
    let text = await metaGet('list/' + version);
    // this version's list is checked against LIST_SHA256 wherever it comes from (an entry planted in the meta cache
    // never governs this version's checks)
    if (text !== null && version === VERSION && !sameHash(await sha256Hex(new TextEncoder().encode(text)), LIST_SHA256)) { text = null; }
    if (text === null) {
        let res;
        try { res = await fetch(urlOf('offline.json'), { cache: 'no-store' }); } catch (e) { return null; }
        if (!res.ok) { return null; }
        const buf = await res.arrayBuffer();
        if (version === VERSION && !sameHash(await sha256Hex(buf), LIST_SHA256)) { return null; }
        text = new TextDecoder().decode(buf);
        let parsed;
        try { parsed = JSON.parse(text); } catch (e) { return null; }
        // another version's list is the site's only when the site still has that version: else none (its page came
        // from the network, and its files do too); remembered for this worker's life
        if (!parsed || parsed.version !== version) { if (version !== VERSION) { mem.lists.set(version, null); } return null; }
        await metaPut('list/' + version, text, !!installing);
    }
    const list = JSON.parse(text);
    mem.lists.set(version, list);
    return list;
}

async function remember(id, version, latest) {
    // the last page's version is kept even when the engine gives no resultingClientId (review o6_r1 N1)
    if (latest) { mem.latest = version; await metaPut('latest', version); }
    if (!id) { return; }
    mem.clients.set(id, version);
    await metaPut('client/' + id, version);
}
async function clientVersion(id) {
    if (id && mem.clients.has(id)) { return mem.clients.get(id); }
    const v = (id && await metaGet('client/' + id)) || await metaGet('latest') || mem.latest || VERSION;
    if (id) { mem.clients.set(id, v); }
    return v;
}

/** a cached answer for rel from the cache name, served only when its bytes are want; a wrong entry is deleted only
 *  when want is that cache's own version's (drop): another version's file reused by hash is left where it is */
async function fromCache(name, rel, want, drop) {
    if (!(await caches.has(name))) { return null; }
    const cache = await caches.open(name);
    const hit = await cache.match(urlOf(rel));
    if (!hit) { return null; }
    const buf = await hit.arrayBuffer();
    if (sameHash(await sha256Hex(buf), want)) { return rebuild(hit, buf); }
    if (drop) { await cache.delete(urlOf(rel)); }
    return null;
}

/* ---- install: this version's page and every precache file, each checked; reused from another version's cache when
   the bytes are the same ---- */
async function precacheOne(cache, rel, entry) {
    if (await fromCache(CACHE, rel, entry.sha256, true)) { return 'have'; }
    for (const name of await caches.keys()) {
        if (!name.startsWith(PREFIX) || name === CACHE || name === META) { continue; }
        const hit = await fromCache(name, rel, entry.sha256, false);
        if (hit) { await cache.put(urlOf(rel), hit); return 'reused'; }
    }
    for (const mode of ['force-cache', 'reload']) {
        let res;
        try { res = await fetch(urlOf(rel), { cache: mode }); } catch (e) { continue; }
        if (!res.ok) { continue; }
        const buf = await res.arrayBuffer();
        if (sameHash(await sha256Hex(buf), entry.sha256)) { await cache.put(urlOf(rel), rebuild(res, buf)); return 'fetched'; }
    }
    throw new Error(rel + ' is not the file of ' + VERSION + ' on the site');
}
async function install() {
    const list = await listFor(VERSION, true);
    if (!list) { throw new Error('offline.json of ' + VERSION + ' could not be read'); }
    const cache = await caches.open(CACHE);
    const todo = [list.page].concat(Object.keys(list.files).filter((r) => list.files[r].precache));
    let next = 0;
    const lane = async () => { while (next < todo.length) { const r = todo[next++]; await precacheOne(cache, r, list.files[r]); } };
    await Promise.all([lane(), lane(), lane(), lane(), lane(), lane()]);
    await self.skipWaiting();
}

/* ---- activate: one version at a time ---- */
async function activate() {
    for (const name of await caches.keys()) {
        if (name.startsWith(PREFIX) && name !== CACHE && name !== META) { await caches.delete(name); }
    }
    await self.clients.claim();
    // the meta cache keeps the clients still open, and the lists of their versions, this one's and the last page's
    const alive = new Set((await self.clients.matchAll({ includeUncontrolled: true, type: 'all' })).map((c) => c.id));
    const meta = await caches.open(META);
    const keep = new Set([VERSION, await metaGet('latest')]);
    const lists = [];
    for (const req of await meta.keys()) {
        const k = decodeURIComponent(req.url.slice(metaKey('').length));
        if (k.startsWith('client/')) {
            if (!alive.has(k.slice(7))) { await meta.delete(req); } else { keep.add(await (await meta.match(req)).text()); }
        } else if (k.startsWith('list/')) { lists.push([k.slice(5), req]); }
    }
    for (const [v, req] of lists) { if (!keep.has(v)) { await meta.delete(req); mem.lists.delete(v); } }
}

/* ---- the kill switch: every evn-ide-* cache deleted, the registration gone, the tabs it had reloaded ----
   Done at install, not at activation: a waiting worker activates only once the old one has no event in flight, which a
   busy workbench tab can hold off indefinitely (Chromium, test_ide_offline.js row 7). The unregistration is not awaited
   here: it is a job queued behind this install's own job, so awaiting it would never end; once it has run the
   registration matches no new navigation, and each tab's reload (asked by a message index.html listens for) comes from
   the site. */
async function kill() {
    let removed = 0;
    for (const name of await caches.keys()) {
        if (name.startsWith(PREFIX)) { await caches.delete(name); removed++; }
    }
    // the reload is asked only when there was something to remove: a page that registers this sw.js again is not
    // reloaded again
    self.registration.unregister().then(async () => {
        if (!removed) { return; }
        for (const c of await self.clients.matchAll({ type: 'window', includeUncontrolled: true })) { c.postMessage({ evnSw: 'reload' }); }
    }, () => undefined);
    await self.skipWaiting();
}

/* ---- fetch ---- */
async function page(e) {
    let timer;
    const late = new Promise((r) => { timer = setTimeout(() => r(null), PAGE_TIMEOUT_MS); });
    const net = await Promise.race([fetch(e.request).then((r) => (r.ok ? r : null), () => null), late]);
    clearTimeout(timer);
    if (net) {
        const buf = await net.arrayBuffer();
        const m = /<meta name="evn-ide-version" content="([^"]+)">/.exec(new TextDecoder().decode(buf));
        await remember(e.resultingClientId, m ? m[1] : 'net:' + Date.now(), true);
        return rebuild(net, buf);
    }
    const list = await listFor(VERSION);
    const hit = list && await fromCache(CACHE, PAGE, list.files[PAGE].sha256, true);
    if (hit) { await remember(e.resultingClientId, VERSION, true); return hit; }
    return fetch(e.request);
}

const refused = (rel, version) => new Response(rel + ' on the site is not the file of this page (' + version + '): reload the page', {
    status: 409, headers: { 'Content-Type': 'text/plain; charset=utf-8', 'X-EVN-SW': 'refused' } });

/** when file() throws (a broken Cache Storage, a full quota): the site's answer, held to the same rule as file()'s
 *  for any path a list in memory names for the page's version - served only at that version's SHA-256, else 409.
 *  With no list in memory (a worker started with its caches broken) nothing can be checked: the network's answer, as
 *  with no worker (review o6_r1_verify V3) */
async function fileFallback(e, rel) {
    const version = (e.clientId && mem.clients.get(e.clientId)) || mem.latest || VERSION;
    const list = mem.lists.get(version);
    const entry = list && list.files[rel];
    const res = await fetch(e.request);
    if (!entry || !res.ok || res.type !== 'basic') { return res; }
    const buf = await res.arrayBuffer();
    return sameHash(await sha256Hex(buf), entry.sha256) ? rebuild(res, buf) : refused(rel, version);
}

async function file(e, rel) {
    const nav = e.request.mode === 'navigate';
    const version = await clientVersion(nav ? '' : e.clientId);
    if (nav) { await remember(e.resultingClientId, version, false); }
    const list = await listFor(version);
    const entry = list && list.files[rel];
    if (!entry) { return fetch(e.request); }
    const cached = await fromCache(PREFIX + version, rel, entry.sha256, true)
        || (version !== VERSION && await fromCache(CACHE, rel, entry.sha256, false));
    if (cached) { return cached; }
    let res = await fetch(e.request);
    if (!res.ok || res.type !== 'basic') { return res; }
    let buf = await res.arrayBuffer();
    if (!sameHash(await sha256Hex(buf), entry.sha256)) {
        // an older copy still fresh in the HTTP cache (a host's max-age): asked of the site once more (review o6_r1 S3)
        res = await fetch(urlOf(rel), { cache: 'reload' });
        buf = res.ok ? await res.arrayBuffer() : new ArrayBuffer(0);
    }
    if (!res.ok || !sameHash(await sha256Hex(buf), entry.sha256)) { return refused(rel, version); }
    const out = rebuild(res, buf);
    // a precache file missing from this version's cache is put back, never into a cache deleted meanwhile (?evn-sw=off)
    if (version === VERSION && entry.precache && await caches.has(CACHE)) { await (await caches.open(CACHE)).put(urlOf(rel), out.clone()); }
    return out;
}

/** a path no list held in memory names is not the IDE's: left to the network, unanswered (§8.2; before any list is
 *  loaded, file() still passes it to the network) */
function unlisted(rel) {
    const lists = [...mem.lists.values()].filter(Boolean);
    return lists.length > 0 && !lists.some((l) => l.files[rel]);
}
if (!KILL) { listFor(VERSION).catch(() => undefined); }
/* the worker's own failure (a full quota, a broken cache) never blocks the page: the network answers instead (a file's
   answer is still checked: fileFallback) */
const orNetwork = (p, e) => p.catch(() => fetch(e.request));
self.addEventListener('install', (e) => { e.waitUntil(KILL ? kill() : install()); });
self.addEventListener('activate', (e) => { if (!KILL) { e.waitUntil(activate()); } });
self.addEventListener('fetch', (e) => {
    if (KILL) { return; }
    const req = e.request;
    if (req.method !== 'GET' || req.headers.has('range')) { return; }
    const u = new URL(req.url);
    if (u.origin !== SCOPE.origin || !u.pathname.startsWith(SCOPE.pathname)) { return; }
    let rel;
    try { rel = decodeURIComponent(u.pathname.slice(SCOPE.pathname.length)); } catch (err) { return; }
    if (PASS.some((p) => rel.startsWith(p))) { return; }
    if (req.mode === 'navigate' && (rel === '' || rel === PAGE)) { e.respondWith(orNetwork(page(e), e)); return; }
    if (rel === '' || rel.endsWith('/') || rel === 'sw.js' || rel === 'offline.json' || unlisted(rel)) { return; }
    e.respondWith(file(e, rel).catch(() => fileFallback(e, rel)));
});
